import ast,json,hashlib
from pathlib import Path
p=json.load(open('proposal.json'));r=json.load(open('runtime.json'))
def validate(x,s,path='study'):
 typ=s.get('type');types={'object':dict,'array':list,'string':str}
 if typ:assert isinstance(x,types[typ]),(path,typ)
 if 'const' in s:assert x==s['const'],path
 if 'enum' in s:assert x in s['enum'],path
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'missing')
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s['items'],path+f'[{i}]')
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert len(p['variants'])==len({v['name'] for v in p['variants']})==len({v['file'] for v in p['variants']})==4
base=ast.parse(Path('history_g0_r0052_block_nonlinear_transfer.py').read_text())
old_methods={n.name:n for n in next(n for n in base.body if isinstance(n,ast.ClassDef)).body if isinstance(n,ast.FunctionDef)}
normalized=[];digests={};method_counts=[]
for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 data=Path(v['file']).read_text();compile(data,v['file'],'exec');tree=ast.parse(data)
 config=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config.value)==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef));methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 init=methods['__init__'];defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in v['config'].items():
  actual=ast.literal_eval(defaults[k]);assert actual==val or isinstance(actual,tuple) and list(actual)==val,(v['file'],k)
 for name,node in old_methods.items():
  if name=='__init__':continue
  target=methods[name]
  if name=='_represent':
   target=ast.parse(ast.unparse(target)).body[0]
   target.body=[s for s in target.body if not(isinstance(s,ast.Assign) and isinstance(s.value,ast.Call) and isinstance(s.value.func,ast.Attribute) and s.value.func.attr=='_history_layout')]
  assert ast.dump(node,include_attributes=False)==ast.dump(target,include_attributes=False),(v['file'],name)
 # Remove only CONFIG/layout-specific default to establish all variants share executable source.
 config.value=ast.Constant(value='NORMALIZED')
 init.args.defaults[-2]=ast.Constant(value='LAYOUT')
 normalized.append(ast.dump(tree,include_attributes=False))
 for node in ast.walk(tree):
  if isinstance(node,(ast.Import,ast.ImportFrom)):
   roots=[node.module.split('.')[0]] if isinstance(node,ast.ImportFrom) else [n.name.split('.')[0] for n in node.names]
   assert set(roots)<={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in ['open','exec','eval','__import__']
 digests[v['file']]=hashlib.sha256(data.encode()).hexdigest();method_counts.append(len(old_methods)-1)
assert len(set(normalized))==1
for anc in json.load(open('workspace.json'))['available_ancestor_sources']:
 assert hashlib.sha256(Path(anc['file']).read_bytes()).hexdigest()==anc['source_sha256'],anc['file']
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
# Compare constructor after removing only the added layout validation/self attribute.
for v in p['variants']:
 new=ast.parse(Path(v['file']).read_text());init=next(n for n in next(n for n in new.body if isinstance(n,ast.ClassDef)).body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 i=next(i for i,a in enumerate(init.args.args) if a.arg=='history_layout');nd=len(init.args.args)-len(init.args.defaults)
 del init.args.defaults[i-nd];del init.args.args[i]
 init.body=[n for n in init.body if not (isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Name) and n.test.left.id=='history_layout') and not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='history_layout' for t in n.targets))]
 assert ast.dump(init,include_attributes=False)==ast.dump(old_methods['__init__'],include_attributes=False),v['file']
print(json.dumps({'schema':'passed full study_schema recursive checks','source':'all variants compile; exact CONFIG/constructor match; executable ASTs identical after CONFIG/default normalization','inheritance':str(method_counts[0])+' inherited methods match (representation matches after removing one layout call); constructor matches after removing layout gate/attribute; no learned construction changes','ancestors':'six authorized ancestor digests and baseline identity verified','sha256':digests},indent=2))
